CREATE OR REPLACE FUNCTION public.challenge_my_point_reviews(_owner_email text) RETURNS SETOF public.challenge_point_reviews LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT r.* FROM public.challenge_point_reviews r JOIN public.giveaway_entries e ON e.id=r.entry_id WHERE e.email=lower(trim(_owner_email)) AND auth.uid() IS NOT NULL AND e.email=public.current_auth_email() ORDER BY r.started_at DESC; $$;